package site

import (
	"fmt"
	"html"
	"regexp"
	"strings"
	"unicode/utf8"
)

// generatedHeader marks every rendered file. A generated file is never edited
// by hand; the header names the source and the command.
const generatedHeader = "<!-- Generated by cmd/gensite from docs/site.json. DO NOT EDIT. -->"

// markdownTokenRE keeps a link or a code span together while wrapping. A link
// may contain spaces, so a plain strings.Fields split would break it.
var markdownTokenRE = regexp.MustCompile("\\[[^\\]]*\\]\\([^)]*\\)[.,;:!?)]*|`[^`]*`[.,;:!?)]*|\\S+")

// markdownLinkRE is used only where Markdown text has to become HTML inside a
// generated section. The source is authored, and the href comes from the page
// table, so this is a formatting step, not an untrusted parser.
var markdownLinkRE = regexp.MustCompile(`\[([^\]]+)\]\(([^)]+)\)`)

var markdownCodeRE = regexp.MustCompile("`([^`]+)`")

// docLinks are the destinations inside docs/. A French page is a sibling under
// docs/fr/, so both trees link to the bare file name; a prefix of ../ would
// resolve to the English page one level up.
func (s Site) docLinks() map[string]string {
	out := map[string]string{}
	for _, page := range s.Pages() {
		if page.Nav {
			out[page.Key] = page.DocsName("en")
		}
	}
	return out
}

// readmeLinks are the destinations from the repository root.
func (s Site) readmeLinks(lang string) map[string]string {
	out := map[string]string{}
	for _, page := range s.Pages() {
		if page.Nav {
			out[page.Key] = page.File(lang)
		}
	}
	return out
}

// assetName resolves one generated asset from the page table. A consumer never
// types an asset file name.
func (s Site) assetName(key, lang string) string {
	for _, page := range s.Pages() {
		if page.Key == key {
			return pathBase(page.File(lang))
		}
	}
	return ""
}

func pathBase(name string) string {
	if index := strings.LastIndexByte(name, '/'); index >= 0 {
		return name[index+1:]
	}
	return name
}

// docAsset is the asset reference from a page under docs/.
func (s Site) docAsset(key, lang string) string {
	if lang == "fr" {
		return "../assets/" + s.assetName(key, lang)
	}
	return "assets/" + s.assetName(key, lang)
}

// readmeAsset is the asset reference from the repository root.
func (s Site) readmeAsset(key, lang string) string {
	return "docs/assets/" + s.assetName(key, lang)
}

// htmlHref turns a documentation link into the final HTML target for a raw
// HTML anchor. Jekyll's relative-links plugin rewrites Markdown links, not raw
// HTML, so the generated sections must name the built page directly.
func htmlHref(href string) string {
	if strings.HasPrefix(href, "http://") || strings.HasPrefix(href, "https://") ||
		strings.HasPrefix(href, "#") || strings.HasPrefix(href, "/") {
		return href
	}
	base, fragment := href, ""
	if index := strings.IndexByte(href, '#'); index >= 0 {
		base, fragment = href[:index], href[index:]
	}
	if strings.HasSuffix(base, ".md") {
		return strings.TrimSuffix(base, ".md") + ".html" + fragment
	}
	return href
}

// inlineHTML turns one authored paragraph into safe inline HTML. Placeholders
// are resolved first, then the small Markdown subset the source uses. The text
// is escaped before the two formatting rules run, so authored copy cannot
// inject markup.
func (s Site) inlineHTML(value, lang string) string {
	text := html.EscapeString(s.text(value, lang))
	text = markdownLinkRE.ReplaceAllStringFunc(text, func(match string) string {
		parts := markdownLinkRE.FindStringSubmatch(match)
		return `<a href="` + htmlHref(parts[2]) + `">` + parts[1] + `</a>`
	})
	text = markdownCodeRE.ReplaceAllString(text, `<code>$1</code>`)
	return text
}

// wrap folds one paragraph at width runes without splitting a link or a code
// span. It preserves no original line breaks: the source is one paragraph per
// value.
func wrap(text string, width int) string {
	tokens := markdownTokenRE.FindAllString(text, -1)
	var out strings.Builder
	line := 0
	for _, token := range tokens {
		size := utf8.RuneCountInString(token)
		switch {
		case line == 0:
			out.WriteString(token)
			line = size
		case line+1+size > width:
			out.WriteString("\n")
			out.WriteString(token)
			line = size
		default:
			out.WriteString(" ")
			out.WriteString(token)
			line += 1 + size
		}
	}
	return out.String()
}

// item renders a list item with a hanging indent.
func item(marker, text string, width int) string {
	body := wrap(text, width-utf8.RuneCountInString(marker))
	return marker + strings.Join(strings.Split(body, "\n"), "\n"+strings.Repeat(" ", utf8.RuneCountInString(marker)))
}

// paragraph appends a wrapped paragraph and one blank line.
func paragraph(out *strings.Builder, text string) {
	out.WriteString(wrap(text, 80))
	out.WriteString("\n\n")
}

// heading appends a level-two heading and one blank line.
func heading(out *strings.Builder, text string) {
	out.WriteString("## ")
	out.WriteString(text)
	out.WriteString("\n\n")
}

// Landing renders docs/index.md or docs/fr/index.md. The page is the ledger:
// a full-bleed twelve-column shell, a grounded answer slip in the first
// viewport, six numbered chapters with a sticky spine, and a CSS-only screen
// index that keeps all eight captures in the document.
func (s Site) Landing(lang string) []byte {
	links := s.docLinks()
	title := s.Hero.Title.For(lang)
	if lang == "fr" {
		title += " (français)"
	}
	var out strings.Builder
	out.WriteString("---\n")
	out.WriteString("layout: default\n")
	fmt.Fprintf(&out, "title: %s\n", yamlQuote(title))
	fmt.Fprintf(&out, "lang: %s\n", yamlQuote(lang))
	// The head override reads this flag, so only the two landings carry the
	// alternate links and the automatic language switch.
	out.WriteString("language_switch: true\n")
	fmt.Fprintf(&out, "description: %s\n", yamlQuote(s.Hero.Promise.For(lang)))
	// The theme's head calls jekyll-seo-tag, which turns this image block into
	// the Open Graph and Twitter card. The path, size and alt text come from
	// the one media table, so the preview cannot drift from the committed PNG.
	out.WriteString("image:\n")
	fmt.Fprintf(&out, "  path: %s\n", yamlQuote("/"+strings.TrimPrefix(s.Media.SocialPreview, "docs/")))
	fmt.Fprintf(&out, "  width: %d\n", s.Media.SocialWidth)
	fmt.Fprintf(&out, "  height: %d\n", s.Media.SocialHeight)
	fmt.Fprintf(&out, "  alt: %s\n", yamlQuote(s.Product+": "+s.Hero.Banner.For(lang)))
	out.WriteString("---\n\n")

	// First viewport: the ask and the working app.
	out.WriteString(`<header class="hero">` + "\n")
	out.WriteString(`  <div class="shell hero-grid">` + "\n")
	out.WriteString(`    <div class="hero-copy">` + "\n")
	fmt.Fprintf(&out, `      <h1 class="promise" id="thesis-title">%s</h1>`+"\n", s.inlineHTML(s.Hero.Promise.For(lang), lang))
	fmt.Fprintf(&out, `      <p class="lede">%s</p>`+"\n", s.inlineHTML(s.Hero.Lede.For(lang), lang))
	fmt.Fprintf(&out, `      <p class="actions"><a class="button" href="%s">%s</a><a class="quiet-link" href="%s">%s</a></p>`+"\n",
		htmlHref(links["install"]), html.EscapeString(s.Install.Title.For(lang)),
		htmlHref(links["first_run"]), html.EscapeString(s.Install.FirstRun.For(lang)))
	fmt.Fprintf(&out, `      <p class="hero-note">%s</p>`+"\n", s.inlineHTML(s.Hero.Note.For(lang), lang))
	out.WriteString("    </div>\n")

	out.WriteString(`    <div class="hero-stage">` + "\n")
	out.WriteString(`      <figure class="app-window">` + "\n")
	out.WriteString(`        <div class="app-bar">` + "\n")
	fmt.Fprintf(&out, `          <img src="%s" width="20" height="20" alt="">`+"\n", html.EscapeString(s.docAsset("mark", lang)))
	fmt.Fprintf(&out, `          <span class="app-name">%s</span>`+"\n", html.EscapeString(s.Product))
	fmt.Fprintf(&out, `          <span class="app-badge">%s</span>`+"\n", html.EscapeString(s.Hero.WindowBadge.For(lang)))
	out.WriteString("        </div>\n")
	home := s.screenshotFor("home")
	fmt.Fprintf(&out, `        <img class="app-shot" src="%s" width="%d" height="%d" loading="eager" decoding="async" alt="%s">`+"\n",
		html.EscapeString(s.mediaAsset(lang, s.ScreenshotPath("home", lang))),
		s.Media.ScreenshotWidth, s.Media.ScreenshotHeight,
		html.EscapeString(s.Product+": "+home.Title.For(lang)))
	out.WriteString("      </figure>\n")

	out.WriteString(`      <aside class="answer-slip" aria-labelledby="slip-label">` + "\n")
	out.WriteString(`        <div class="slip-head">` + "\n")
	fmt.Fprintf(&out, `          <p class="slip-label" id="slip-label">%s</p>`+"\n", html.EscapeString(s.Hero.Answer.Label.For(lang)))
	out.WriteString(`          <span class="slip-meta">` + "\n")
	fmt.Fprintf(&out, `            <span class="slip-sample">%s</span>`+"\n", html.EscapeString(s.Hero.Answer.Sample.For(lang)))
	fmt.Fprintf(&out, `            <span class="chip">%s</span>`+"\n", html.EscapeString(s.Hero.Answer.Mode.For(lang)))
	out.WriteString("          </span>\n")
	out.WriteString("        </div>\n")
	fmt.Fprintf(&out, `        <p class="slip-question">%s</p>`+"\n", s.inlineHTML(s.Hero.Answer.Question.For(lang), lang))
	fmt.Fprintf(&out, `        <p class="slip-answer">%s</p>`+"\n", s.inlineHTML(s.Hero.Answer.Body.For(lang), lang))
	out.WriteString(`        <ol class="citations">` + "\n")
	for index, citation := range s.Hero.Answer.Citations {
		date := citation.Date.For(lang)
		out.WriteString("          <li>\n")
		fmt.Fprintf(&out, `            <span class="citation-mark" aria-hidden="true">%02d</span>`+"\n", index+1)
		out.WriteString(`            <span class="citation-main">` + "\n")
		fmt.Fprintf(&out, `              <span class="citation-subject">%s</span>`+"\n", html.EscapeString(citation.Subject.For(lang)))
		fmt.Fprintf(&out, `              <span class="citation-meta">%s · %s</span>`+"\n", html.EscapeString(citation.Sender), html.EscapeString(date))
		out.WriteString("            </span>\n")
		out.WriteString("          </li>\n")
	}
	out.WriteString("        </ol>\n")
	fmt.Fprintf(&out, `        <p class="slip-caption">%s</p>`+"\n", s.inlineHTML(s.Hero.Answer.Caption.For(lang), lang))
	out.WriteString("      </aside>\n")
	out.WriteString("    </div>\n")
	out.WriteString("  </div>\n")
	out.WriteString("</header>\n\n")

	// 01 Ask first: three mechanism panels, the mode table and the guarantee.
	out.WriteString(`<section class="section section-ask" aria-labelledby="ask-title">` + "\n")
	out.WriteString(`  <div class="shell">` + "\n")
	s.sectionHead(&out, lang, "ask-title", s.Ask.Title.For(lang), s.Ask.Lead.For(lang), false)
	out.WriteString(`    <div class="ask-bento">` + "\n")
	for index, mechanism := range s.Ask.Items {
		class := "ask-card"
		switch index {
		case 0:
			class += " ask-card-grounding"
		case 1:
			class += " ask-card-local"
		case 2:
			class += " ask-card-trace"
		}
		fmt.Fprintf(&out, `      <article class="%s">`+"\n", class)
		out.WriteString(`        <div class="card-top">` + "\n")
		fmt.Fprintf(&out, `          <span class="card-number">%02d</span>`+"\n", index+1)
		fmt.Fprintf(&out, `          <span class="card-tag">%s</span>`+"\n", html.EscapeString(mechanism.Tag.For(lang)))
		out.WriteString("        </div>\n")
		fmt.Fprintf(&out, `        <h3>%s</h3>`+"\n", html.EscapeString(mechanism.Title.For(lang)))
		fmt.Fprintf(&out, `        <p>%s</p>`+"\n", s.inlineHTML(mechanism.Body.For(lang), lang))
		switch index {
		case 0:
			out.WriteString(`        <ul class="mini-cites">` + "\n")
			for _, citation := range s.Hero.Answer.Citations {
				out.WriteString(`          <li>` + "\n")
				out.WriteString(`            <span class="mini-dot" aria-hidden="true"></span>` + "\n")
				fmt.Fprintf(&out, `            <span class="mini-subject">%s</span>`+"\n", html.EscapeString(citation.Subject.For(lang)))
				fmt.Fprintf(&out, `            <span class="mini-sender">%s</span>`+"\n", html.EscapeString(citation.Sender))
				out.WriteString("          </li>\n")
			}
			out.WriteString("        </ul>\n")
		case 1:
			out.WriteString(`        <div class="mode-chips" aria-hidden="true">` + "\n")
			for modeIndex, mode := range s.Ask.Modes.Items {
				modeClass := "mode-chip"
				if modeIndex == 1 {
					modeClass += " is-on"
				}
				fmt.Fprintf(&out, `          <span class="%s">%s</span>`+"\n", modeClass, html.EscapeString(mode.Name.For(lang)))
			}
			out.WriteString("        </div>\n")
		case 2:
			out.WriteString(`        <div class="mini-history">` + "\n")
			out.WriteString(`          <span class="mini-history-dot" aria-hidden="true"></span>` + "\n")
			fmt.Fprintf(&out, `          <span>%s</span>`+"\n", html.EscapeString(s.Hero.Answer.Question.For(lang)))
			out.WriteString("        </div>\n")
		}
		out.WriteString("      </article>\n")
	}
	out.WriteString("    </div>\n")

	out.WriteString(`    <div class="ask-lower">` + "\n")
	out.WriteString(`      <div class="mode-panel">` + "\n")
	fmt.Fprintf(&out, `        <h3 id="modes-title">%s</h3>`+"\n", html.EscapeString(s.Ask.Modes.Title.For(lang)))
	out.WriteString(`        <table class="mode-table" aria-labelledby="modes-title">` + "\n")
	out.WriteString(`          <thead><tr>`)
	for _, column := range s.Ask.Modes.Columns {
		fmt.Fprintf(&out, `<th scope="col">%s</th>`, html.EscapeString(column.For(lang)))
	}
	out.WriteString("</tr></thead>\n")
	out.WriteString(`          <tbody>` + "\n")
	for _, mode := range s.Ask.Modes.Items {
		out.WriteString("            <tr>\n")
		fmt.Fprintf(&out, `              <th scope="row" data-label="%s"><span class="mode-name">%s</span></th>`+"\n",
			html.EscapeString(s.Ask.Modes.Columns[0].For(lang)), html.EscapeString(mode.Name.For(lang)))
		fmt.Fprintf(&out, `              <td data-label="%s">%s</td>`+"\n",
			html.EscapeString(s.Ask.Modes.Columns[1].For(lang)), s.inlineHTML(mode.Answers.For(lang), lang))
		fmt.Fprintf(&out, `              <td data-label="%s">%s</td>`+"\n",
			html.EscapeString(s.Ask.Modes.Columns[2].For(lang)), s.inlineHTML(mode.Model.For(lang), lang))
		out.WriteString("            </tr>\n")
	}
	out.WriteString("          </tbody>\n        </table>\n")
	out.WriteString("      </div>\n")
	out.WriteString(`      <div class="guarantee-panel">` + "\n")
	fmt.Fprintf(&out, `        <p class="pull">%s</p>`+"\n", s.inlineHTML(s.Ask.Guarantee.For(lang), lang))
	fmt.Fprintf(&out, `        <p class="note">%s</p>`+"\n", s.inlineHTML(s.Ask.Note.For(lang), lang))
	fmt.Fprintf(&out, `        <p class="chapter-link"><a href="%s">%s</a></p>`+"\n",
		htmlHref(links["ask"]), html.EscapeString(s.Ask.Guide.For(lang)))
	out.WriteString("      </div>\n")
	out.WriteString("    </div>\n")
	out.WriteString("  </div>\n")
	out.WriteString("</section>\n\n")

	// 02 The queue: a ranked invented mail table and the three mechanisms.
	out.WriteString(`<section class="section section-queue" aria-labelledby="queue-title">` + "\n")
	out.WriteString(`  <div class="shell">` + "\n")
	s.sectionHead(&out, lang, "queue-title", s.Differences.Title.For(lang), s.Differences.Lead.For(lang), false)
	out.WriteString(`    <div class="queue-layout">` + "\n")
	s.queueTable(&out, lang)
	out.WriteString(`      <div class="queue-notes">` + "\n")
	out.WriteString(`        <div class="queue-band">` + "\n")
	for index, difference := range s.Differences.Items {
		out.WriteString(`          <article class="queue-item">` + "\n")
		fmt.Fprintf(&out, `            <span class="band-number" aria-hidden="true">%02d</span>`+"\n", index+1)
		fmt.Fprintf(&out, `            <p class="card-tag">%s</p>`+"\n", html.EscapeString(difference.Tag.For(lang)))
		fmt.Fprintf(&out, `            <h3>%s</h3>`+"\n", html.EscapeString(difference.Title.For(lang)))
		fmt.Fprintf(&out, `            <p>%s</p>`+"\n", s.inlineHTML(difference.Body.For(lang), lang))
		out.WriteString("          </article>\n")
	}
	out.WriteString("        </div>\n")
	out.WriteString("      </div>\n")
	out.WriteString("    </div>\n")
	out.WriteString("  </div>\n")
	out.WriteString("</section>\n\n")

	// 03 The screens: a pill index and one large stage.
	out.WriteString(`<section class="section section-screens" aria-labelledby="screens-title">` + "\n")
	out.WriteString(`  <div class="shell">` + "\n")
	s.sectionHead(&out, lang, "screens-title", s.Media.Title.For(lang), s.Media.Lead.For(lang), false)
	out.WriteString(`    <div class="screens-panel">` + "\n")
	out.WriteString(`      <fieldset class="screen-index" aria-describedby="screen-hint">` + "\n")
	fmt.Fprintf(&out, `        <legend class="visually-hidden">%s</legend>`+"\n", html.EscapeString(s.Media.IndexLabel.For(lang)))
	out.WriteString(`        <div class="screen-index-head">` + "\n")
	fmt.Fprintf(&out, `          <p class="screen-index-label" aria-hidden="true">%s</p>`+"\n", html.EscapeString(s.Media.IndexLabel.For(lang)))
	fmt.Fprintf(&out, `          <p class="screen-hint" id="screen-hint"><span class="screen-hint-pointer">%s</span><span class="screen-hint-touch">%s</span></p>`+"\n",
		s.inlineHTML(s.Media.IndexHint.For(lang), lang), s.inlineHTML(s.Media.IndexHintTouch.For(lang), lang))
	out.WriteString("        </div>\n")
	out.WriteString(`        <div class="screen-list">` + "\n")
	for index, shot := range s.Media.Screenshots {
		checked := ""
		if index == 0 {
			checked = " checked"
		}
		fmt.Fprintf(&out, `          <label class="screen-tab" for="screen-%s">`+"\n", shot.Key)
		fmt.Fprintf(&out, `            <input class="screen-radio" type="radio" name="screen" id="screen-%s"%s>`+"\n", shot.Key, checked)
		fmt.Fprintf(&out, `            <span class="screen-num" aria-hidden="true">%02d</span>`+"\n", index+1)
		fmt.Fprintf(&out, `            <span class="screen-name">%s</span>`+"\n", html.EscapeString(shot.Title.For(lang)))
		out.WriteString("          </label>\n")
	}
	out.WriteString("        </div>\n")
	out.WriteString(`        <div class="screen-stage">` + "\n")
	for index, shot := range s.Media.Screenshots {
		asset := s.mediaAsset(lang, s.ScreenshotPath(shot.Key, lang))
		loading := "lazy"
		if index == 0 {
			loading = "eager"
		}
		fmt.Fprintf(&out, `          <figure class="shot" id="shot-%s">`+"\n", shot.Key)
		out.WriteString(`            <div class="screen-frame">` + "\n")
		fmt.Fprintf(&out, `              <img src="%s" width="%d" height="%d" loading="%s" decoding="async" alt="%s">`+"\n",
			html.EscapeString(asset),
			s.Media.ScreenshotWidth, s.Media.ScreenshotHeight, loading,
			html.EscapeString(s.Product+": "+shot.Title.For(lang)))
		out.WriteString("            </div>\n")
		fmt.Fprintf(&out, `            <a class="shot-full" href="%s" target="_blank" rel="noopener">%s</a>`+"\n",
			html.EscapeString(asset), html.EscapeString(s.Media.ViewFull.For(lang)))
		fmt.Fprintf(&out, `            <figcaption><strong>%s</strong> %s</figcaption>`+"\n",
			html.EscapeString(shot.Title.For(lang)), s.inlineHTML(shot.Caption.For(lang), lang))
		out.WriteString("          </figure>\n")
	}
	out.WriteString("        </div>\n")
	out.WriteString("      </fieldset>\n")
	out.WriteString("    </div>\n")
	out.WriteString("  </div>\n")
	out.WriteString("</section>\n\n")

	// 04 What leaves the machine.
	out.WriteString(`<section class="section section-privacy" aria-labelledby="boundary-title">` + "\n")
	out.WriteString(`  <div class="shell">` + "\n")
	out.WriteString(`    <div class="privacy-panel">` + "\n")
	s.sectionHead(&out, lang, "boundary-title", s.Boundary.Title.For(lang), s.Boundary.Lead.For(lang), true)
	out.WriteString(`      <div class="privacy-grid">` + "\n")
	for _, side := range []struct {
		title Localized
		items []Localized
		key   string
	}{
		{s.Boundary.LeavesTitle, s.Boundary.Leaves, "leaves"},
		{s.Boundary.StaysTitle, s.Boundary.Stays, "stays"},
	} {
		fmt.Fprintf(&out, `        <div class="boundary-col boundary-%s">`+"\n", side.key)
		fmt.Fprintf(&out, `          <h3>%s</h3>`+"\n", html.EscapeString(side.title.For(lang)))
		out.WriteString("          <ol>\n")
		for _, entry := range side.items {
			fmt.Fprintf(&out, `            <li>%s</li>`+"\n", s.inlineHTML(entry.For(lang), lang))
		}
		out.WriteString("          </ol>\n")
		out.WriteString("        </div>\n")
	}
	out.WriteString("      </div>\n")
	fmt.Fprintf(&out, `      <p class="note">%s</p>`+"\n", s.inlineHTML(s.Boundary.Note.For(lang), lang))
	out.WriteString("    </div>\n")
	out.WriteString("  </div>\n")
	out.WriteString("</section>\n\n")

	// 05 What it cannot do yet.
	out.WriteString(`<section class="section section-limits" aria-labelledby="limits-title">` + "\n")
	out.WriteString(`  <div class="shell">` + "\n")
	s.sectionHead(&out, lang, "limits-title", s.Limits.Title.For(lang), s.Limits.Lead.For(lang), false)
	out.WriteString(`    <div class="limits-panel">` + "\n")
	out.WriteString(`      <ol class="limits-list">` + "\n")
	for _, limit := range s.Limits.Items {
		out.WriteString("        <li>\n")
		out.WriteString(`          <div class="limit-text">` + "\n")
		fmt.Fprintf(&out, `            <h3>%s</h3>`+"\n", html.EscapeString(limit.Title.For(lang)))
		fmt.Fprintf(&out, `            <p>%s</p>`+"\n", s.inlineHTML(limit.Body.For(lang), lang))
		out.WriteString("          </div>\n")
		out.WriteString("        </li>\n")
	}
	out.WriteString("      </ol>\n")
	out.WriteString("    </div>\n")
	out.WriteString("  </div>\n")
	out.WriteString("</section>\n\n")

	// 06 Install: the working close.
	out.WriteString(`<section class="section section-install" aria-labelledby="install-title">` + "\n")
	out.WriteString(`  <div class="shell">` + "\n")
	out.WriteString(`    <div class="install-panel">` + "\n")
	s.sectionHead(&out, lang, "install-title", s.Install.Title.For(lang), s.Install.Lead.For(lang), true)
	out.WriteString(`      <div class="install-grid">` + "\n")
	out.WriteString(`        <div class="install-file-block">` + "\n")
	fmt.Fprintf(&out, `          <p class="install-label">%s</p>`+"\n", html.EscapeString(s.Install.Panel.For(lang)))
	fmt.Fprintf(&out, `          <pre class="install-file"><code>%s</code></pre>`+"\n", html.EscapeString(s.Install.File))
	fmt.Fprintf(&out, `          <p class="note">%s</p>`+"\n", s.inlineHTML(s.Install.FileNote.For(lang), lang))
	out.WriteString(`          <ul class="install-facts">` + "\n")
	for _, fact := range s.Install.Facts {
		fmt.Fprintf(&out, `            <li>%s</li>`+"\n", s.inlineHTML(fact.For(lang), lang))
	}
	out.WriteString("          </ul>\n")
	out.WriteString("        </div>\n")
	out.WriteString(`        <div class="install-action-block">` + "\n")
	fmt.Fprintf(&out, `          <p class="install-caveat">%s</p>`+"\n", s.inlineHTML(s.Install.Caveat.For(lang), lang))
	fmt.Fprintf(&out, `          <p class="actions"><a class="button button-light" href="%s">%s</a></p>`+"\n",
		html.EscapeString(s.Repository+"/releases"), html.EscapeString(s.Install.Download.For(lang)))
	fmt.Fprintf(&out, `          <p><a class="quiet-link quiet-link-light" href="%s">%s</a></p>`+"\n",
		htmlHref(links["first_run"]), html.EscapeString(s.Install.FirstRun.For(lang)))
	fmt.Fprintf(&out, `          <p class="install-note">%s</p>`+"\n", s.inlineHTML(s.Install.Note.For(lang), lang))
	out.WriteString("        </div>\n")
	out.WriteString("      </div>\n")
	out.WriteString("    </div>\n")
	out.WriteString("  </div>\n")
	out.WriteString("</section>\n\n")

	// The status is a slim line. The sitemap footer belongs to the layout.
	out.WriteString(`<section class="status" aria-labelledby="status-title">` + "\n")
	out.WriteString(`  <div class="shell status-line">` + "\n")
	fmt.Fprintf(&out, `    <h2 id="status-title">%s</h2>`+"\n", html.EscapeString(s.Status.Title.For(lang)))
	fmt.Fprintf(&out, `    <p>%s</p>`+"\n", s.inlineHTML(s.Status.Body.For(lang), lang))
	out.WriteString("  </div>\n")
	out.WriteString("</section>\n")

	return []byte(out.String())
}

// sectionHead writes the paired title and lead that opens every section.
func (s Site) sectionHead(out *strings.Builder, lang, id, title, lead string, dark bool) {
	class := "section-head"
	if dark {
		class += " section-head-dark"
	}
	fmt.Fprintf(out, `    <div class="%s">`+"\n", class)
	fmt.Fprintf(out, `      <h2 id="%s">%s</h2>`+"\n", id, html.EscapeString(title))
	fmt.Fprintf(out, `      <p class="section-lead">%s</p>`+"\n", s.inlineHTML(lead, lang))
	out.WriteString("    </div>\n")
}

// screenshotFor returns one media row by key. The hero uses the queue capture
// while the screen index keeps the one media order.
func (s Site) screenshotFor(key string) Screenshot {
	for _, shot := range s.Media.Screenshots {
		if shot.Key == key {
			return shot
		}
	}
	if len(s.Media.Screenshots) > 0 {
		return s.Media.Screenshots[0]
	}
	return Screenshot{}
}

// queueTable renders the invented ranked queue. It sits before the three
// mechanism columns as the second proof: a dense table of mail the queue would
// show, with one action value per row in a mono cell.
func (s Site) queueTable(out *strings.Builder, lang string) {
	queue := s.Differences.Queue
	out.WriteString(`      <div class="queue-panel">` + "\n")
	fmt.Fprintf(out, `        <p class="queue-label">%s</p>`+"\n", html.EscapeString(queue.Label.For(lang)))
	out.WriteString(`        <table class="queue-table">` + "\n")
	out.WriteString(`          <thead><tr>`)
	for _, column := range queue.Columns {
		fmt.Fprintf(out, `<th scope="col">%s</th>`, html.EscapeString(column.For(lang)))
	}
	out.WriteString("</tr></thead>\n")
	out.WriteString(`          <tbody>` + "\n")
	for index, item := range queue.Items {
		out.WriteString("            <tr>\n")
		fmt.Fprintf(out, `              <th scope="row" class="queue-rank">%02d</th>`+"\n", index+1)
		fmt.Fprintf(out, `              <td class="queue-subject">%s</td>`+"\n", html.EscapeString(item.Subject.For(lang)))
		fmt.Fprintf(out, `              <td class="queue-sender">%s</td>`+"\n", html.EscapeString(item.Sender))
		fmt.Fprintf(out, `              <td class="queue-action"><span>%s</span></td>`+"\n",
			html.EscapeString(item.Action.For(lang)))
		out.WriteString("            </tr>\n")
	}
	out.WriteString("          </tbody>\n        </table>\n")
	out.WriteString("      </div>\n")
}

// Readme renders README.md or README.fr.md as the repository front door.
func (s Site) Readme(lang string) []byte {
	links := s.readmeLinks(lang)
	readmeText := func(value string) string { return s.textFor(value, lang, links) }
	var out strings.Builder
	out.WriteString(generatedHeader)
	out.WriteString("\n\n")
	fmt.Fprintf(&out, "# %s\n\n", s.Product)
	paragraph(&out, "**"+s.Hero.Promise.For(lang)+"**")
	paragraph(&out, s.Hero.Lede.For(lang))
	fmt.Fprintf(&out, "![%s](%s)\n\n", s.bannerAlt(lang), s.readmeAsset("banner", lang))
	out.WriteString(s.readmeNav(lang))
	out.WriteString("\n\n")

	heading(&out, s.Ask.Title.For(lang))
	paragraph(&out, readmeText(s.Ask.Lead.For(lang)))
	for _, example := range s.Ask.Examples {
		text := fmt.Sprintf("**%s** %s", example.Question.For(lang), readmeText(example.Body.For(lang)))
		out.WriteString(item("- ", text, 80))
		out.WriteString("\n")
	}
	out.WriteString("\n")
	paragraph(&out, readmeText(s.Ask.Guarantee.For(lang)))
	paragraph(&out, readmeText(s.Ask.Note.For(lang)))
	fmt.Fprintf(&out, "[%s](%s)\n\n", s.Ask.Guide.For(lang), links["ask"])

	heading(&out, s.Differences.Title.For(lang))
	for _, difference := range s.Differences.Items {
		text := fmt.Sprintf("**%s** %s", difference.Title.For(lang), readmeText(difference.Body.For(lang)))
		out.WriteString(item("- ", text, 80))
		out.WriteString("\n")
	}
	out.WriteString("\n")

	heading(&out, s.Boundary.Title.For(lang))
	paragraph(&out, readmeText(s.Boundary.Lead.For(lang)))
	fmt.Fprintf(&out, "**%s**\n\n", s.Boundary.LeavesTitle.For(lang))
	for _, entry := range s.Boundary.Leaves {
		out.WriteString(item("- ", readmeText(entry.For(lang)), 80))
		out.WriteString("\n")
	}
	out.WriteString("\n")
	fmt.Fprintf(&out, "**%s**\n\n", s.Boundary.StaysTitle.For(lang))
	for _, entry := range s.Boundary.Stays {
		out.WriteString(item("- ", readmeText(entry.For(lang)), 80))
		out.WriteString("\n")
	}
	out.WriteString("\n")
	paragraph(&out, readmeText(s.Boundary.Note.For(lang)))

	heading(&out, s.Limits.Title.For(lang))
	for _, limit := range s.Limits.Items {
		text := fmt.Sprintf("**%s** %s", limit.Title.For(lang), readmeText(limit.Body.For(lang)))
		out.WriteString(item("- ", text, 80))
		out.WriteString("\n")
	}
	out.WriteString("\n")

	heading(&out, s.Install.Title.For(lang))
	paragraph(&out, readmeText(s.Install.Lead.For(lang)))
	paragraph(&out, "**Windows.** "+readmeText(s.Install.Windows.For(lang)))
	out.WriteString("```text\n")
	out.WriteString(s.Install.File)
	out.WriteString("\n```\n\n")
	paragraph(&out, readmeText(s.Install.FileNote.For(lang)))
	fmt.Fprintf(&out, "[%s](%s)\n\n", s.Install.FirstRun.For(lang), links["first_run"])

	heading(&out, s.Status.Title.For(lang))
	paragraph(&out, readmeText(s.Status.Body.For(lang)))

	heading(&out, s.Build.Title.For(lang))
	paragraph(&out, readmeText(s.Build.Requirements.For(lang)))
	out.WriteString("```bash\n")
	out.WriteString(strings.TrimRight(s.Build.Commands, "\n"))
	out.WriteString("\n```\n\n")
	paragraph(&out, readmeText(s.Build.Note.For(lang)))

	heading(&out, s.License.Title.For(lang))
	paragraph(&out, readmeText(s.License.Body.For(lang)))

	fmt.Fprintf(&out, "[%s](%s)\n", s.docsLabel(lang), s.docsHome(lang))
	return []byte(strings.TrimRight(out.String(), "\n") + "\n")
}

// readmeNav is the language switch, the documentation home, the public
// destinations and the published site.
func (s Site) readmeNav(lang string) string {
	links := s.readmeLinks(lang)
	docs := "docs/index.md"
	if lang == "fr" {
		docs = "docs/fr/index.md"
	}
	parts := []string{languageSwitch(lang), fmt.Sprintf("[%s](%s)", s.docsLabel(lang), docs)}
	for _, item := range s.Nav {
		href, ok := links[item.Key]
		if !ok {
			continue
		}
		parts = append(parts, fmt.Sprintf("[%s](%s)", item.Label.For(lang), href))
	}
	parts = append(parts, fmt.Sprintf("[%s](%s)", s.siteLabel(lang), s.docsHome(lang)))
	return strings.Join(parts, " · ")
}

func languageSwitch(lang string) string {
	if lang == "fr" {
		return "[English](README.md)"
	}
	return "[Français](README.fr.md)"
}

func (s Site) sourceLabel(lang string) string {
	if lang == "fr" {
		return "Code source"
	}
	return "Source"
}

func (s Site) siteLabel(lang string) string {
	if lang == "fr" {
		return "Site de documentation"
	}
	return "Docs site"
}

func (s Site) privacyLabel(lang string) string {
	if lang == "fr" {
		return "Confidentialité"
	}
	return "Privacy"
}

// docsHome is the published documentation home in the page's language.
func (s Site) docsHome(lang string) string {
	if lang == "fr" {
		return strings.TrimSuffix(s.DocsSite, "/") + "/fr/"
	}
	return s.DocsSite
}

// bannerAlt is the accessible description of the generated banner.
func (s Site) bannerAlt(lang string) string {
	return s.Product + ": " + s.Hero.Banner.For(lang)
}
